C340_R = [('LX = X9 + 3, LW = 12', 'LX = X9, LW = 12   /* c340: 주차장 입구가 아래 가운데로 */'), ("    { const zL = P.z0 + (P.z1 - P.z0) * 0.5, pc = (x, z) => { const c = chParked(x, z, 0, false); c.tutS = P; }, br = (x, z) => { const c = chParked(x, z, 0, true); c.tutS = P; };   // c339: 주차장 한가운데 가로 한 줄 — 양 끝 벽까지 경찰차로 막은 진지 (경찰차 5 + 바리케이트 1), 바로 뒤에 경찰차 2 더 · 경찰 14 · 군인 4가 가로로 뭉쳐 있다 (저격수 없음)\n      [0, 1, 2, 3, 4, 5].forEach((k) => (k === 3 ? br : pc)(P.x0 + 1.0 + k * 2.0, zL));\n      pc(cx - 2.6, zL - 3.4); pc(cx + 2.6, zL - 3.4);\n      for (let k = 0; k < 7; k++) post(P, 'police', P.x0 + 1.0 + k * 1.67, zL - 1.4);\n      for (const [t, dx] of [['police', -4.6], ['soldier', -3.2], ['police', -1.4], ['soldier', -0.4], ['soldier', 0.6], ['police', 1.4], ['soldier', 3.2], ['police', 4.6]]) post(P, t, cx + dx, zL - (Math.abs(dx) > 2 && Math.abs(dx) < 4 ? 2.4 : 4.9));\n      post(P, 'police', cx, zL - 5.9); post(P, 'police', cx - 3.4, zL - 5.6); post(P, 'police', cx + 3.4, zL - 5.6); }", "    { const zL = P.z0 + (P.z1 - P.z0) * 0.5, J = (a) => (Math.random() * 2 - 1) * a, cars = [], ppl = [];   // c340: 영화처럼 듬성듬성 — 가운데 띠에 경찰차 7 · 바리케이트 1을 들쭉날쭉 (조금씩 돌아가 있고 앞뒤로 어긋남), 경찰은 차 뒤·옆에 붙어서 제멋대로, 군인 4는 그 뒤 아무 데나\n      const free = (x, z, r, L) => L.every(([a, b, rr]) => Math.hypot(a - x, b - z) > r + rr);\n      for (let k = 0; k < 8; k++) { let x = 0, z = 0, h = 0; for (let t = 0; t < 80; t++) { x = P.x0 + 1.0 + k * (10 / 7) + J(0.45); z = zL + J(1.3); h = (Math.random() < 0.3 ? J(0.9) : J(0.35)) + (Math.random() < 0.15 ? Math.PI / 2 : 0); if (free(x, z, 1.15, cars)) break; }\n        cars.push([x, z, 1.15]); const c = chParked(x, z, h, k === 4); c.tutS = P; }   // 다섯 번째는 바리케이트\n      const put2 = (t, x0, z0, spread) => { let x = 0, z = 0; for (let n = 0; n < 60; n++) { x = Math.max(P.x0 + 0.6, Math.min(P.x1 - 0.6, x0 + J(spread))); z = z0 + J(spread * 0.7); if (free(x, z, 0.5, ppl) && free(x, z, 1.25, cars.map(([a, b]) => [a, b, 0]))) break; } ppl.push([x, z, 0.42]); post(P, t, x, z); };\n      cars.forEach(([x, z], k) => { if (k === 4) return; put2('police', x + J(0.6), z - 1.7 - Math.random() * 0.6, 0.5); put2('police', x + (Math.random() < 0.5 ? -1 : 1) * (0.9 + Math.random() * 0.4), z - 1.0 - Math.random() * 1.2, 0.4); });   // 차마다 경찰 2 (뒤 하나 · 옆구리 하나)\n      for (let k = 0; k < 4; k++) put2('soldier', cx + J(4.2), zL - 3.0 - Math.random() * 2.6, 0.6); }")]
